"""Size source acquisition from preserved viewport samples; no rendering or admission."""
import json,math,pathlib
from shapely.geometry import box
P=pathlib.Path(__file__).parent
f=json.loads((P/'PRESERVED_FRAME_BOUNDS.json').read_text())['frames'];g=json.loads((P/'SOURCE_GAP_GEOMETRY_AUDIT.json').read_text());rows=[]
for c in g['cells']:
 visible=[r for r in f if box(*r['bounds']).intersection(box(*c['bounds'])).area>0]
 # Screen sampling contract, not a claim that geographic metres are uniform.
 per_degree=max(max(1080/(r['bounds'][2]-r['bounds'][0]),1920/(r['bounds'][3]-r['bounds'][1])) for r in visible)
 native_min=math.ceil(per_degree);power=2**math.ceil(math.log2(native_min));factor=2**math.ceil(math.log2(2*per_degree))
 rows.append({'tile':c['tile'],'mappedLandPresent':c['mappedLandAreaSquareDegrees']>0,'opticalPublished':c['opticalCatalogPresent'],'dsmPublished':c['dsmCatalogPresent'],'maxOutputPixelsPerDegree':per_degree,'minimumSamplesPerDegreeNoOversampling':native_min,'powerOfTwoSamplesPerDegree':power,'twoTimesSamplingPowerOfTwo':factor,'acquisitionRoute':'PUBLISHED_LAND_TILE_QUALIFICATION' if c['mappedLandAreaSquareDegrees']>0 else 'EXPLICIT_WATER_MASK_AND_SOURCE_POLICY_REQUIRED','gutterSamples':2})
land=[r for r in rows if r['mappedLandPresent']]
result={'schema':'WORLD_ENGINE_SOURCE_LOD_ACQUISITION_PLAN_V1','status':'PLANNING_ONLY_NOT_ADMISSION','output':[1080,1920],'basis':'Preserved actual frame bounds only; no camera recompile or old-suite rerun','viewportMinHeightDegrees':min(r['bounds'][3]-r['bounds'][1] for r in f),'viewportMinWidthDegrees':min(r['bounds'][2]-r['bounds'][0] for r in f),'mappedLandCellCount':len(land),'noMappedLandCellCount':len(rows)-len(land),'allMappedLandCellsPublishedOptical':all(r['opticalPublished'] for r in land),'allMappedLandCellsPublishedDSM':all(r['dsmPublished'] for r in land),'landCellPowerOfTwoCounts':{str(n):sum(r['powerOfTwoSamplesPerDegree']==n for r in land) for n in sorted({r['powerOfTwoSamplesPerDegree'] for r in land})},'landRGBRawBytesAt1xPlus2pxGutter':sum((r['powerOfTwoSamplesPerDegree']+4)**2*3 for r in land),'landRGBRawBytesAt2xPlus2pxGutter':sum((r['twoTimesSamplingPowerOfTwo']+4)**2*3 for r in land),'limitations':['Numerical sampling plan only, not visual source approval. Source optical point-spread, masks, reprojection, filter footprints and seam treatment still need qualification.','DSM geometry/error needs its own criteria; do not assume the optical raster grid is an approved terrain mesh.','Published nominal one-degree COGs have 12000 samples per side; use overviews and bounded windows rather than bulk 10m originals.','The current Studio path does not yet bind a qualified multi-tile/LOD source set. Do not install this plan as a BAKED_RELIEF source.'],'cells':rows,'gpuStarts':0,'renders':0,'productionAdmitted':False}
(P/'SOURCE_LOD_ACQUISITION_PLAN.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k!='cells'},indent=2))
